function getRoleBadgeLabel(role) {
  const map = {
    worker: 'ASHA Worker',
    patient: 'Patient',
    doctor: 'Doctor',
    shop_owner: 'Pharmacy',
    lab_staff: 'Diagnostic Lab',
    facility: 'Facility Admin',
    admin: 'Coordinator'
  };
  return map[role] || 'User';
}

